-- Synthetic-only fixture. Apply after canonical v112 baseline, Phase 36 and Phase 46.
CREATE OR REPLACE FUNCTION auth.role()
RETURNS text LANGUAGE sql STABLE
AS $auth_role$
  SELECT NULLIF(current_setting('request.jwt.claim.role', true), '')
$auth_role$;

INSERT INTO public.roles (id, name, code) VALUES
 ('61000000-0000-0000-0000-000000000001', 'Admin', 'admin'),
 ('61000000-0000-0000-0000-000000000002', 'Pharmacist', 'pharmacist'),
 ('61000000-0000-0000-0000-000000000003', 'Doctor', 'doctor'),
 ('61000000-0000-0000-0000-000000000004', 'Super Admin', 'super_admin')
ON CONFLICT (code) DO NOTHING;

-- Canonical production doctors already hold emr.create; seed that baseline permission
-- explicitly because the v112 schema replay intentionally contains no role data.
INSERT INTO public.permissions (code, name, module, action)
VALUES ('emr.create', 'Create clinical records', 'emr', 'create')
ON CONFLICT (code) DO NOTHING;

INSERT INTO public.role_permissions (role_id, permission_id)
SELECT r.id, p.id
FROM public.roles AS r
JOIN public.permissions AS p ON p.code = 'emr.create'
WHERE r.code = 'doctor'
ON CONFLICT DO NOTHING;

-- Match the live broad Admin and Super Admin permission sets without granting clinical prescription authority.
INSERT INTO public.role_permissions (role_id, permission_id)
SELECT r.id, p.id
FROM public.roles AS r
JOIN public.permissions AS p ON p.code IN ('emr.create', 'pharmacy.create')
WHERE r.code IN ('admin', 'super_admin')
ON CONFLICT DO NOTHING;

-- The live pharmacist role has pharmacy.create; seed it to exercise the
-- SECURITY DEFINER prescription-creation authorization boundary.
INSERT INTO public.permissions (code, name, module, action)
VALUES ('pharmacy.create', 'Create pharmacy records', 'pharmacy', 'create')
ON CONFLICT (code) DO NOTHING;

INSERT INTO public.role_permissions (role_id, permission_id)
SELECT r.id, p.id
FROM public.roles AS r
JOIN public.permissions AS p ON p.code = 'pharmacy.create'
WHERE r.code = 'pharmacist'
ON CONFLICT DO NOTHING;

INSERT INTO public.role_permissions (role_id, permission_id)
SELECT r.id, p.id
